properties.query:
let email_events = EmailEvents | where ThreatTypes has "Macro" or AttachmentExtension in ("xlsm", "docm", "xlsb") | summarize email_time=min(TimeGenerated) by RecipientEmailAddress;
let ps_events = SecurityEvent | where EventID == 4103 and ScriptBlockText has_any ("Invoke-WebRequest", "Invoke-Expression", "DownloadString") | summarize ps_time=min(TimeGenerated) by TargetUserName;
let exfil_events = NetworkEvents | where BytesSent > 5000000 | summarize exfil_time=min(TimeGenerated) by SourceIP;
email_events | join kind=inner ps_events on $left.RecipientEmailAddress == $right.TargetUserName | where ps_time - email_time between (0min .. 120min)
